const COLORS=['#ef4444','#f59e0b','#22c55e','#3b82f6','#8b5cf6','#ec4899','#111827'];
const CONFIG_KEY='rotas.secure.config.v2';
const VAULT_KEY='rotas.secure.vault.v2';
const PREFS_KEY='rotas.secure.prefs.v2';
const LEGACY_KEY='rotas.v1';
const DEFAULT_ITERATIONS=450000;
const state={data:{routes:[]},routeId:null,map:null,menu:false,key:null,locked:true,lastActivity:Date.now(),failedUnlocks:0,routeUI:{search:'',status:'all',color:'all',groupByColor:false}};
let modalStop=null, modalContext=null, pendingBackup=null, pendingSearchQuery='';

function uid(){return crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2)}
function esc(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function toast(s){const e=document.querySelector('#toast');if(!e)return;e.textContent=s;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2400)}
function route(){return state.data.routes.find(r=>r.id===state.routeId)}
function getConfig(){try{return JSON.parse(localStorage.getItem(CONFIG_KEY))}catch{return null}}
function getPrefs(){try{return {...{addressSearchConsent:false,onlineMapConsent:false,autoLockMinutes:15,markerSize:'medium'},...(JSON.parse(localStorage.getItem(PREFS_KEY))||{})}}catch{return{addressSearchConsent:false,onlineMapConsent:false,autoLockMinutes:15,markerSize:'medium'}}}
function setPrefs(p){localStorage.setItem(PREFS_KEY,JSON.stringify({...getPrefs(),...p}))}
function b64(buf){const bytes=new Uint8Array(buf),chunk=0x8000,parts=[];for(let i=0;i<bytes.length;i+=chunk)parts.push(String.fromCharCode(...bytes.subarray(i,i+chunk)));return btoa(parts.join(''))}
function unb64(s){const bin=atob(s),out=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)out[i]=bin.charCodeAt(i);return out.buffer}
function randomSalt(){const a=new Uint8Array(16);crypto.getRandomValues(a);return b64(a.buffer)}
async function deriveKey(secret,saltB64,iterations=DEFAULT_ITERATIONS){const raw=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret.normalize('NFKC')),{name:'PBKDF2'},false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',hash:'SHA-256',salt:new Uint8Array(unb64(saltB64)),iterations},raw,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function encryptBytes(buf,key=state.key){const iv=new Uint8Array(12);crypto.getRandomValues(iv);const data=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,buf);return{iv:iv.buffer,data}}
async function decryptBytes(record,key=state.key){return crypto.subtle.decrypt({name:'AES-GCM',iv:new Uint8Array(record.iv)},key,record.data)}
async function encryptJSON(obj,key=state.key){const enc=new TextEncoder().encode(JSON.stringify(obj));const r=await encryptBytes(enc,key);return{iv:b64(r.iv),data:b64(r.data)}}
async function decryptJSON(record,key=state.key){const plain=await decryptBytes({iv:unb64(record.iv),data:unb64(record.data)},key);return JSON.parse(new TextDecoder().decode(plain))}
async function saveVault(){if(!state.key)throw new Error('locked');const encrypted=await encryptJSON(state.data);localStorage.setItem(VAULT_KEY,JSON.stringify(encrypted))}
function touch(){state.lastActivity=Date.now()}
function render(){if(state.locked)return renderLock();state.routeId?renderRoute():renderHome()}

function renderSetup(){const legacy=!!localStorage.getItem(LEGACY_KEY);document.querySelector('#app').innerHTML=`<div class="auth-shell"><div class="auth-card"><div class="lockmark">🔐</div><h1>Configurar proteção local</h1><p>Rotas, nomes, dados do mandado e documentos serão criptografados neste dispositivo antes de serem gravados.</p>${legacy?'<div class="success">Dados da versão anterior foram encontrados. Ao criar a senha, o aplicativo tentará migrá-los para o armazenamento criptografado.</div>':''}<div class="warning"><strong>Não há recuperação de senha.</strong> Se você esquecer, os dados criptografados não poderão ser lidos. Use pelo menos 8 caracteres.</div><div id="setupError" class="warning" style="display:none"></div><input id="setupPass1" type="password" autocomplete="new-password" placeholder="PIN/senha (mín. 8 caracteres)"><input id="setupPass2" type="password" autocomplete="new-password" placeholder="Repita o PIN/senha"><button id="setupCreateBtn" class="primary" type="button">Criar proteção</button><div class="security-note">A criptografia protege os dados em repouso. Ela não protege contra um aparelho já desbloqueado e comprometido, malware, capturas de tela ou alguém que conheça sua senha.</div><div class="tiny" style="margin-top:12px;text-align:center">versão 3.6</div></div></div>`;const btn=document.querySelector('#setupCreateBtn');if(btn)btn.addEventListener('click',setupSecurity);['setupPass1','setupPass2'].forEach(id=>document.querySelector('#'+id)?.addEventListener('keydown',e=>{if(e.key==='Enter')setupSecurity()}))}
async function setupSecurity(){const a=document.querySelector('#setupPass1')?.value||'',b=document.querySelector('#setupPass2')?.value||'',err=document.querySelector('#setupError');const showErr=m=>{if(err){err.style.display='block';err.textContent=m}toast(m)};if(a.length<8)return showErr('Use pelo menos 8 caracteres.');if(a!==b)return showErr('As senhas não conferem.');const btn=document.querySelector('#setupCreateBtn');if(btn){btn.disabled=true;btn.textContent='Preparando proteção…'}try{if(!window.isSecureContext)throw new Error('A página não está em contexto seguro (HTTPS).');if(!window.crypto?.subtle)throw new Error('Web Crypto não está disponível neste navegador.');const config={version:2,salt:randomSalt(),iterations:DEFAULT_ITERATIONS,createdAt:Date.now()};const key=await deriveKey(a,config.salt,config.iterations);state.key=key;state.data={routes:[]};const legacy=localStorage.getItem(LEGACY_KEY);if(legacy){try{const parsed=JSON.parse(legacy);if(Array.isArray(parsed.routes)){state.data=parsed;await migrateLegacyDocs(parsed,key)}}catch(e){console.warn('Falha na migração legada',e)}}localStorage.setItem(CONFIG_KEY,JSON.stringify(config));await saveVault();localStorage.removeItem(LEGACY_KEY);state.locked=false;touch();render();toast('Proteção ativada.')}catch(e){console.error('Falha ao configurar proteção:',e);showErr('Falha ao criar proteção: '+(e?.message||'erro desconhecido'));if(btn){btn.disabled=false;btn.textContent='Criar proteção'}}}

function renderLock(){if(!getConfig())return renderSetup();if(state.map){state.map.remove();state.map=null}document.querySelector('#app').innerHTML=`<div class="auth-shell"><div class="auth-card"><div class="lockmark">🔒</div><h1>Rotas bloqueadas</h1><p>Digite seu PIN/senha para descriptografar os dados locais.</p><input id="unlockPass" type="password" autocomplete="current-password" placeholder="PIN/senha" onkeydown="if(event.key==='Enter')unlock()"><button class="primary" onclick="unlock()">Desbloquear</button><div class="divider"></div><button class="linkbtn" onclick="resetLocalData()">Esqueci a senha / apagar dados locais</button></div></div>`;setTimeout(()=>document.querySelector('#unlockPass')?.focus(),50)}
async function unlock(){const pass=document.querySelector('#unlockPass')?.value||'',cfg=getConfig();if(!pass)return;const btn=document.querySelector('.auth-card .primary');btn.disabled=true;btn.innerHTML='<span class="spinner"></span> Desbloqueando…';try{const key=await deriveKey(pass,cfg.salt,cfg.iterations);const vault=JSON.parse(localStorage.getItem(VAULT_KEY));if(!vault)throw new Error('vault missing');const data=await decryptJSON(vault,key);if(!Array.isArray(data.routes))throw new Error('bad vault');state.key=key;state.data=data;state.locked=false;state.failedUnlocks=0;touch();render()}catch(e){state.failedUnlocks++;const delay=Math.min(3000,400*state.failedUnlocks);setTimeout(()=>{toast('PIN/senha incorreto.');renderLock()},delay)}}
function lockNow(){state.key=null;state.data={routes:[]};state.routeId=null;state.locked=true;state.menu=false;if(state.map){state.map.remove();state.map=null}closeModal(false);renderLock()}
async function resetLocalData(){const word=prompt('Isso apaga rotas e documentos criptografados deste navegador. Digite APAGAR para confirmar.');if(word!=='APAGAR')return;await clearSecureDocs();localStorage.removeItem(CONFIG_KEY);localStorage.removeItem(VAULT_KEY);localStorage.removeItem(LEGACY_KEY);state.key=null;state.data={routes:[]};state.locked=true;renderSetup()}

function renderHome(){if(state.map){state.map.remove();state.map=null}const deliveredCount=r=>r.stops.filter(s=>s.status==='delivered').length;document.querySelector('#app').innerHTML=`<main class="shell"><header class="topbar"><h1>Rotas</h1><button class="iconbtn" onclick="securitySettings()" title="Segurança">🔒</button><button class="iconbtn" onclick="importBackup()" title="Importar backup">↥</button><button class="iconbtn" onclick="exportBackup()" title="Exportar backup">↧</button></header><section class="content"><div class="hero"><h2>Planejador de diligências</h2><p>Dados e documentos ficam criptografados neste dispositivo. O código do aplicativo pode estar no GitHub sem levar os mandados junto.</p></div><div class="route-grid">${state.data.routes.length?state.data.routes.map(r=>`<article class="route-card" onclick="openRoute('${r.id}')"><div class="meta"><h3>${esc(r.name)}</h3><div class="muted">${r.stops.length} parada${r.stops.length===1?'':'s'} · ${deliveredCount(r)} entregue${deliveredCount(r)===1?'':'s'}</div></div><button class="iconbtn" onclick="event.stopPropagation();editRoute('${r.id}')">•••</button></article>`).join(''):`<div class="empty">Nenhuma rota criada ainda.</div>`}</div></section><button class="fab" onclick="newRoute()">＋ Criar rota</button></main>`}
function newRoute(){showModal(`<h2>Nova rota</h2><div class="field"><label>Nome da rota</label><input id="routeName" placeholder="Ex.: Centro — terça-feira" autofocus></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="createRoute()">Criar</button></div>`)}
async function createRoute(){const n=document.querySelector('#routeName').value.trim();if(!n)return;const r={id:uid(),name:n,createdAt:Date.now(),stops:[]};state.data.routes.unshift(r);await saveVault();closeModal();openRoute(r.id)}
function editRoute(id){const r=state.data.routes.find(x=>x.id===id);showModal(`<h2>Editar rota</h2><div class="field"><label>Nome</label><input id="routeName" value="${esc(r.name)}"></div><div class="modal-actions"><button class="danger" onclick="deleteRoute('${id}')">Excluir</button><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="renameRoute('${id}')">Salvar</button></div>`)}
async function renameRoute(id){const r=state.data.routes.find(x=>x.id===id),n=document.querySelector('#routeName').value.trim();if(n){r.name=n;await saveVault();closeModal();render()}}
async function deleteRoute(id){if(!confirm('Excluir esta rota, todas as paradas e seus documentos?'))return;const r=state.data.routes.find(x=>x.id===id);for(const s of r?.stops||[]){for(const d of s.docs||[])await secureDbDelete(d.id);if(s.signature?.id)await secureDbDelete(s.signature.id);}state.data.routes=state.data.routes.filter(r=>r.id!==id);await saveVault();closeModal();if(state.routeId===id)state.routeId=null;render()}
function openRoute(id){state.routeId=id;render()}
function backHome(){state.routeId=null;state.menu=false;render()}

function filteredStops(){const r=route(),ui=state.routeUI,q=(ui.search||'').trim().toLowerCase();return (r?.stops||[]).map((s,i)=>({s,i})).filter(({s})=>{if(ui.status!=='all'&&(s.status||'pending')!==ui.status)return false;if(ui.color!=='all'&&s.color!==ui.color)return false;if(q){const hay=[s.name,s.number,s.address,s.notes].filter(Boolean).join(' ').toLowerCase();if(!hay.includes(q))return false}return true})}
function routeListHTML(){const items=filteredStops();if(!items.length)return `<div class="empty compact">Nenhuma diligência corresponde aos filtros.</div>`;if(!state.routeUI.groupByColor)return items.map(({s,i})=>stopHTML(s,i)).join('');const groups=[];for(const c of COLORS){const g=items.filter(x=>x.s.color===c);if(g.length)groups.push(`<div class="color-group"><div class="color-group-title"><span class="color-dot" style="background:${c}"></span><strong>${g.length} diligência${g.length===1?'':'s'}</strong></div>${g.map(({s,i})=>stopHTML(s,i)).join('')}</div>`)}const other=items.filter(x=>!COLORS.includes(x.s.color));if(other.length)groups.push(`<div class="color-group"><div class="color-group-title"><span class="color-dot"></span><strong>${other.length} diligência${other.length===1?'':'s'}</strong></div>${other.map(({s,i})=>stopHTML(s,i)).join('')}</div>`);return groups.join('')}
function renderRoute(){const r=route();if(!r)return backHome();const counts={pending:0,failed:0,delivered:0};r.stops.forEach(s=>counts[s.status||'pending']=(counts[s.status||'pending']||0)+1);const prefs=getPrefs();const missingCount=r.stops.filter(s=>s.address&&(!Number.isFinite(s.lat)||!Number.isFinite(s.lng))).length;const mapMode=prefs.onlineMapConsent&&navigator.onLine?'Ruas online':'Mapa espacial offline';document.querySelector('#app').innerHTML=`<main class="shell premium-shell"><header class="topbar premium-topbar"><button class="iconbtn" onclick="backHome()">‹</button><div class="route-title"><h1>${esc(r.name)}</h1><small>${r.stops.length} diligência${r.stops.length===1?'':'s'}</small></div>${missingCount?`<button class="iconbtn locate-header-btn" onclick="locateMissingAddresses()" title="Localizar ${missingCount} endereços sem coordenadas">⌖<span>${missingCount}</span></button>`:''}<button class="iconbtn" onclick="printRouteReport()" title="Relatório">▤</button><button class="iconbtn" onclick="toggleMenu()">⋮</button>${state.menu?`<div class="menu premium-menu"><button onclick="newStop()">＋ Adicionar diligência</button><button onclick="importStops()">⇩ Importar dados</button><button onclick="locateMissingAddresses()">⌖ Localizar ${missingCount||''} endereços</button><button onclick="downloadImportTemplate()">Baixar modelo CSV</button><button onclick="printRouteReport()">Imprimir / relatório</button><button onclick="visualSettings()">Aparência do mapa</button><button onclick="editRoute('${r.id}')">Editar rota</button><button onclick="toggleOnlineMap()">${prefs.onlineMapConsent?'Usar mapa offline':'Ativar ruas online'}</button><button onclick="optimizeRoute()">Ordenar por proximidade (opcional)</button><button onclick="exportBackup()">Exportar backup</button><button onclick="securitySettings()">Segurança e privacidade</button><button onclick="lockNow()">Bloquear agora</button></div>`:''}</header><section class="mapwrap"><div id="map" class="map"></div><div class="map-note map-note-row premium-map-note"><div><strong>${mapMode}</strong><div>${prefs.onlineMapConsent&&navigator.onLine?'Mapa com ruas ativo. Dados pessoais e documentos permanecem locais.':'Marcadores e arquivos permanecem disponíveis offline.'}</div><div id="mapProviderStatus" class="map-provider-status">${prefs.onlineMapConsent&&navigator.onLine?'Carregando mapa…':''}</div></div><button class="map-toggle" onclick="toggleOnlineMap()">${prefs.onlineMapConsent?'Offline':'Ruas'}</button></div>${missingCount?`<div class="geo-map-alert"><div><strong>${missingCount} endereço${missingCount===1?'':'s'} sem ponto no mapa</strong><span>Toque para localizar automaticamente.</span></div><button onclick="locateMissingAddresses()">⌖ Localizar agora</button></div>`:''}<div class="sheet premium-sheet"><div class="grab"></div>${missingCount?`<div class="geo-alert"><div><strong>${missingCount} endereço${missingCount===1?'':'s'} sem localização no mapa</strong><span>Localize agora para transformar os endereços importados em marcadores.</span></div><button class="primary mini" onclick="locateMissingAddresses()">⌖ Localizar</button></div>`:''}<div class="status-summary"><button class="summary-chip ${state.routeUI.status==='all'?'selected':''}" onclick="setRouteStatusFilter('all')"><b>${r.stops.length}</b> total</button><button class="summary-chip ${state.routeUI.status==='pending'?'selected':''}" onclick="setRouteStatusFilter('pending')"><b>${counts.pending}</b> pendentes</button><button class="summary-chip sum-failed ${state.routeUI.status==='failed'?'selected':''}" onclick="setRouteStatusFilter('failed')"><b>${counts.failed}</b> não entregues</button><button class="summary-chip sum-delivered ${state.routeUI.status==='delivered'?'selected':''}" onclick="setRouteStatusFilter('delivered')"><b>${counts.delivered}</b> entregues</button></div><div class="route-tools"><div class="searchbox"><span>⌕</span><input id="routeSearch" value="${esc(state.routeUI.search)}" oninput="setRouteSearch(this.value)" placeholder="Buscar nome, nº do mandado ou endereço"></div><button class="toolbtn ${state.routeUI.groupByColor?'active':''}" onclick="toggleGroupByColor()" title="Agrupar por cor">◉ Cor</button></div><div class="color-filters"><button class="color-filter ${state.routeUI.color==='all'?'active':''}" onclick="setRouteColorFilter('all')">Todas</button>${COLORS.map(c=>`<button class="color-filter dot-only ${state.routeUI.color===c?'active':''}" style="--dot:${c}" onclick="setRouteColorFilter('${c}')" aria-label="Filtrar por cor"></button>`).join('')}</div><div class="sheet-head"><strong>Diligências</strong><div class="sheet-actions"><button class="secondary mini" onclick="importStops()">Importar</button><button class="primary mini" onclick="newStop()">＋ Mandado</button></div></div><div class="stop-list">${routeListHTML()}</div></div></section></main>`;setTimeout(initMap,0)}
function stopHTML(s,i){const status=s.status||'pending',num=s.number?`<span class="warrant-no">${esc(s.number)}</span>`:'';return `<div class="stop premium-stop" onclick="viewStop('${s.id}')"><div class="badge ${status}" style="background:${status==='delivered'?'#9ca3af':s.color}">${i+1}</div><div class="stop-main"><div class="stop-name">${esc(s.name||'Sem nome')} ${num}</div><div class="stop-address">${esc(s.address||'Coordenadas cadastradas')}</div><div class="stop-meta">${status==='pending'?'Pendente':status==='failed'?'Não entregue':'Entregue'}${(s.docs||[]).length?` · ${(s.docs||[]).length} doc.`:''}${s.signature?' · assinatura':''}</div></div><span class="chevron">›</span></div>`}
function setRouteSearch(v){state.routeUI.search=v;const list=document.querySelector('.stop-list');if(list)list.innerHTML=routeListHTML()}
function setRouteStatusFilter(v){state.routeUI.status=v;renderRoute()}
function setRouteColorFilter(v){state.routeUI.color=v;renderRoute()}
function toggleGroupByColor(){state.routeUI.groupByColor=!state.routeUI.groupByColor;renderRoute()}
function toggleMenu(){state.menu=!state.menu;renderRoute()}
function toggleOnlineMap(){const p=getPrefs();if(p.onlineMapConsent){setPrefs({onlineMapConsent:false});state.menu=false;renderRoute();return}showModal(`<h2>Ativar ruas no mapa</h2><p>Para desenhar ruas dentro do aplicativo, os blocos da área visualizada serão carregados do OpenStreetMap. O serviço externo pode receber o IP da conexão e a região do mapa que você está vendo.</p><div class="security-note"><strong>Não são enviados:</strong> nome da pessoa, número ou dados do mandado, documentos, assinatura ou status da diligência.</div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Continuar offline</button><button class="primary" onclick="allowOnlineMap()">Ativar ruas</button></div>`)}
function allowOnlineMap(){setPrefs({onlineMapConsent:true});closeModal();state.menu=false;renderRoute()}
function markerPx(){const v=getPrefs().markerSize;return v==='small'?28:v==='large'?44:36}
function setMapProviderStatus(text,kind=''){const e=document.querySelector('#mapProviderStatus');if(!e)return;e.textContent=text;e.className='map-provider-status '+kind}
function showTileFailure(){setMapProviderStatus('Não foi possível carregar o fundo de ruas. Os marcadores e dados continuam disponíveis.','error');const el=document.querySelector('#map');if(el&&!el.querySelector('.map-load-error')){const d=document.createElement('div');d.className='map-load-error';d.innerHTML='<strong>Mapa de ruas indisponível</strong><span>Verifique a internet e toque em Ruas novamente.</span>';el.appendChild(d)}}
function addOnlineBaseLayer(map){let primaryErrors=0,usingFallback=false,fallbackErrors=0;const primary=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'});primary.on('tileload',()=>setMapProviderStatus('Ruas carregadas · OpenStreetMap','ok'));primary.on('tileerror',()=>{primaryErrors++;if(primaryErrors>=4&&!usingFallback){usingFallback=true;try{map.removeLayer(primary)}catch(_){}setMapProviderStatus('Tentando provedor alternativo…','warn');const fallback=L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png',{subdomains:'abcd',maxZoom:20,attribution:'© OpenStreetMap contributors © CARTO'});fallback.on('tileload',()=>setMapProviderStatus('Ruas carregadas · mapa alternativo','ok'));fallback.on('tileerror',()=>{fallbackErrors++;if(fallbackErrors>=6)showTileFailure()});fallback.addTo(map)}});primary.addTo(map);return primary}
function initMap(){if(state.map){state.map.remove();state.map=null}const prefs=getPrefs();if(!window.L||!navigator.onLine||!prefs.onlineMapConsent){renderOfflineSpatialMap();if(!window.L&&prefs.onlineMapConsent)setMapProviderStatus('Biblioteca do mapa não carregou. Atualize a página.','error');return}state.map=L.map('map',{zoomControl:false,attributionControl:true}).setView([-9.913,-63.041],13);addOnlineBaseLayer(state.map);L.control.zoom({position:'topright'}).addTo(state.map);const pts=[],px=markerPx();route().stops.forEach((s,i)=>{if(Number.isFinite(s.lat)&&Number.isFinite(s.lng)){pts.push([s.lat,s.lng]);const icon=L.divIcon({className:`marker-${getPrefs().markerSize}`,html:`<div class="pin ${s.status||''}" style="--pin-size:${px}px;background:${s.status==='delivered'?'#9ca3af':s.color}"><span>${i+1}</span></div>`,iconSize:[px+4,px+8],iconAnchor:[(px+4)/2,px+4]});L.marker([s.lat,s.lng],{icon,title:s.name||s.address||`Diligência ${i+1}`}).addTo(state.map).on('click',()=>viewStop(s.id))}});if(pts.length>1)state.map.fitBounds(pts,{padding:[55,55]});else if(pts.length===1)state.map.setView(pts[0],16);setTimeout(()=>state.map?.invalidateSize(),120)}
function renderOfflineSpatialMap(){const el=document.querySelector('#map');if(!el)return;const located=route().stops.map((s,i)=>({s,i})).filter(x=>Number.isFinite(x.s.lat)&&Number.isFinite(x.s.lng));if(!located.length){el.innerHTML=`<div class="offline-map-empty"><strong>Mapa espacial offline</strong><span>Cadastre coordenadas nos mandados para visualizar os pontos aqui mesmo sem internet.</span></div>`;return}const lats=located.map(x=>x.s.lat),lngs=located.map(x=>x.s.lng),minLat=Math.min(...lats),maxLat=Math.max(...lats),minLng=Math.min(...lngs),maxLng=Math.max(...lngs),midLat=(minLat+maxLat)/2,cos=Math.max(.15,Math.cos(midLat*Math.PI/180)),latSpan=Math.max(maxLat-minLat,.0025),lngSpan=Math.max((maxLng-minLng)*cos,.0025),pad=.1;el.innerHTML=`<div class="offline-spatial"><div class="offline-compass">N ↑</div>${located.map(({s,i})=>{const x=pad+(1-2*pad)*(((s.lng-minLng)*cos/lngSpan)+((lngSpan-(maxLng-minLng)*cos)/2/lngSpan));const y=1-(pad+(1-2*pad)*(((s.lat-minLat)/latSpan)+((latSpan-(maxLat-minLat))/2/latSpan)));return `<button class="offline-pin pin ${s.status||''}" style="--pin-size:${markerPx()}px;left:${Math.max(5,Math.min(95,x*100))}%;top:${Math.max(7,Math.min(93,y*100))}%;background:${s.status==='delivered'?'#9ca3af':s.color}" onclick="viewStop('${s.id}')" title="${esc(s.name||s.address||'Diligência')}"><span>${i+1}</span></button>`}).join('')}<div class="offline-caption">Posição relativa dos mandados · funciona sem internet</div></div>`}

function newStop(){state.menu=false;stopModal({id:uid(),name:'',number:'',address:'',notes:'',color:COLORS[3],status:'pending',lat:null,lng:null,docs:[],signature:null},true)}
function stopModal(source,isNew=false){modalStop=JSON.parse(JSON.stringify(source));modalStop.number=modalStop.number||'';modalContext={type:'stop',isNew,originalId:source.id,addedDocIds:[],removedDocIds:[]};showModal(`<div class="modal-title-row"><div><h2>${isNew?'Novo mandado':'Editar mandado'}</h2><div class="muted">Dados, documentos e assinatura ficam criptografados no aparelho.</div></div>${!isNew?`<button class="secondary mini" onclick="printStop('${source.id}')">Imprimir</button>`:''}</div><div class="form-grid"><div class="field"><label>Número do mandado</label><input id="warrantNumber" value="${esc(modalStop.number)}" placeholder="Ex.: 7001234-56.2026.8.22.0002"></div><div class="field"><label>Nome da pessoa</label><input id="personName" value="${esc(modalStop.name)}" placeholder="Nome da pessoa"></div></div><div class="field"><label>Buscar / endereço</label><div class="row"><input id="address" value="${esc(modalStop.address)}" placeholder="Digite o endereço"><button class="secondary" onclick="searchAddress()">Buscar online</button></div><div class="tiny" style="margin-top:6px">Na busca online, somente o texto do endereço é enviado ao serviço de geocodificação.</div><div id="searchResults"></div></div><div class="field"><label>Dados / observações do mandado</label><textarea id="notes" placeholder="Observações, referência, contato e demais dados">${esc(modalStop.notes)}</textarea></div><div class="field"><label>Cor / classificação visual</label><div class="colors">${COLORS.map(c=>`<button class="color ${c===modalStop.color?'active':''}" style="background:${c}" data-color="${c}" onclick="pickColor(this)"></button>`).join('')}</div></div><div class="field"><label>Coordenadas</label><div class="row"><input id="lat" inputmode="decimal" value="${modalStop.lat??''}" placeholder="Latitude"><input id="lng" inputmode="decimal" value="${modalStop.lng??''}" placeholder="Longitude"></div><button class="secondary" style="margin-top:8px" onclick="useLocation()">Usar minha localização atual</button></div><div class="field"><label>Mandados / documentos</label><div id="docs">${docsEditHTML(modalStop.docs)}</div><div class="button-row"><button class="secondary" onclick="chooseDocs()">＋ Anexar PDF ou imagem</button></div></div><div class="field"><label>Assinatura</label><div id="signatureBox">${signatureEditHTML(modalStop.signature)}</div><div class="button-row"><button class="secondary" onclick="openSignaturePad()">✍ ${modalStop.signature?'Refazer assinatura':'Coletar assinatura'}</button><button class="secondary" onclick="importSignatureImage()">⇩ Importar assinatura</button></div></div>${!isNew?`<div class="field"><label>Status</label>${statusHTML(modalStop.status,'temp')}</div>`:''}<div class="modal-actions">${!isNew?`<button class="danger" onclick="deleteStop('${source.id}')">Excluir</button>`:''}<button class="secondary" onclick="cancelStopModal()">Cancelar</button><button class="primary" onclick="saveStop('${source.id}',${isNew})">Salvar</button></div>`)}
function pickColor(el){document.querySelectorAll('.color').forEach(x=>x.classList.remove('active'));el.classList.add('active')}
function statusHTML(st,mode='direct'){return `<div class="status-grid"><button class="${st==='pending'?'active':''}" onclick="${mode==='temp'?"setStatusTemp('pending',this)":"setStatusDirect('pending',this)"}">Pendente</button><button class="${st==='failed'?'active':''}" onclick="${mode==='temp'?"setStatusTemp('failed',this)":"setStatusDirect('failed',this)"}">✕ Não entregue</button><button class="${st==='delivered'?'active':''}" onclick="${mode==='temp'?"setStatusTemp('delivered',this)":"setStatusDirect('delivered',this)"}">✓ Entregue</button></div>`}
function setStatusTemp(st,el){modalStop.status=st;el.parentElement.querySelectorAll('button').forEach(b=>b.classList.remove('active'));el.classList.add('active')}
async function setStatusDirect(st,el){const s=route()?.stops.find(x=>x.id===modalContext?.originalId);if(!s)return;s.status=st;await saveVault();el.parentElement.querySelectorAll('button').forEach(b=>b.classList.remove('active'));el.classList.add('active');setTimeout(()=>{closeModal(false);renderRoute()},160)}
async function searchAddress(){const q=document.querySelector('#address').value.trim();if(!q)return;const prefs=getPrefs();if(!prefs.addressSearchConsent){showConsentForSearch(q);return}await performAddressSearch(q)}
function showConsentForSearch(q){pendingSearchQuery=q;showNestedConfirm(`<h2>Busca de endereço</h2><p>Para localizar o endereço, <strong>somente o texto digitado no campo de endereço</strong> será enviado ao Nominatim/OpenStreetMap. Nome da pessoa, dados do mandado, documentos e status permanecem locais.</p><div class="warning">O endereço e seu IP poderão ser processados pelo serviço externo. Você pode continuar sem busca online usando endereço e coordenadas manualmente.</div><div class="modal-actions"><button class="secondary" onclick="closeNestedConfirm()">Cancelar</button><button class="primary" onclick="allowAddressSearch()">Permitir neste dispositivo</button></div>`)}
async function allowAddressSearch(){setPrefs({addressSearchConsent:true});const q=pendingSearchQuery;pendingSearchQuery='';closeNestedConfirm();await performAddressSearch(q)}
async function performAddressSearch(q){const box=document.querySelector('#searchResults');if(!box)return;box.innerHTML='<div class="muted" style="padding:8px"><span class="spinner"></span> Buscando…</div>';try{const res=await fetch('https://nominatim.openstreetmap.org/search?format=json&limit=5&countrycodes=br&q='+encodeURIComponent(q),{cache:'no-store',referrerPolicy:'no-referrer'});if(!res.ok)throw new Error('search');const arr=await res.json();box.className='search-results';box.innerHTML=arr.length?arr.map((x,i)=>`<div class="search-result" onclick="selectAddress(${i})">${esc(x.display_name)}</div>`).join(''):'<div class="search-result">Nenhum resultado.</div>';box._results=arr}catch{box.innerHTML='<div class="search-result">Busca indisponível. Preencha o endereço e as coordenadas manualmente.</div>'}}
function selectAddress(i){const box=document.querySelector('#searchResults'),x=box._results?.[i];if(!x)return;document.querySelector('#address').value=x.display_name;document.querySelector('#lat').value=x.lat;document.querySelector('#lng').value=x.lon;box.innerHTML=''}
function useLocation(){navigator.geolocation?.getCurrentPosition(p=>{document.querySelector('#lat').value=p.coords.latitude;document.querySelector('#lng').value=p.coords.longitude;toast('Localização preenchida.')},()=>toast('Não foi possível obter a localização.'))}
async function saveStop(id,isNew){const r=route();modalStop.address=document.querySelector('#address').value.trim();modalStop.name=document.querySelector('#personName').value.trim();modalStop.number=document.querySelector('#warrantNumber')?.value.trim()||'';modalStop.notes=document.querySelector('#notes').value.trim();modalStop.color=document.querySelector('.color.active')?.dataset.color||COLORS[3];const lat=parseFloat(document.querySelector('#lat').value.replace(',','.')),lng=parseFloat(document.querySelector('#lng').value.replace(',','.'));modalStop.lat=Number.isFinite(lat)?lat:null;modalStop.lng=Number.isFinite(lng)?lng:null;if(!modalStop.address&&!Number.isFinite(modalStop.lat)){toast('Informe um endereço ou coordenadas.');return}if(isNew)r.stops.push(modalStop);else{const idx=r.stops.findIndex(x=>x.id===id);if(idx>=0)r.stops[idx]=modalStop}for(const rid of modalContext.removedDocIds)await secureDbDelete(rid);await saveVault();modalContext.addedDocIds=[];modalContext.removedDocIds=[];closeModal(false);renderRoute()}
async function cancelStopModal(){for(const id of modalContext?.addedDocIds||[])await secureDbDelete(id);closeModal(false)}
async function deleteStop(id){if(!confirm('Excluir esta parada, seus documentos e assinatura?'))return;const r=route(),s=r.stops.find(x=>x.id===id);for(const d of s?.docs||[])await secureDbDelete(d.id);if(s?.signature?.id)await secureDbDelete(s.signature.id);for(const id2 of modalContext?.addedDocIds||[])await secureDbDelete(id2);r.stops=r.stops.filter(s=>s.id!==id);await saveVault();closeModal(false);renderRoute()}
function viewStop(id){const s=route().stops.find(x=>x.id===id),i=route().stops.indexOf(s);modalStop=JSON.parse(JSON.stringify(s));modalContext={type:'view',originalId:id};showModal(`<div class="stop-view-head"><div class="view-badge" style="background:${s.status==='delivered'?'#9ca3af':s.color}">${i+1}</div><div><h2>${esc(s.name||'Diligência')}</h2><div class="muted">${s.number?`Mandado ${esc(s.number)} · `:''}Parada ${i+1}/${route().stops.length}</div></div></div><div class="detail-card"><label>Endereço</label><div>${esc(s.address||'—')}</div></div>${s.notes?`<div class="detail-card"><label>Dados do mandado</label><div style="white-space:pre-wrap">${esc(s.notes)}</div></div>`:''}<div class="field"><label>Status</label>${statusHTML(s.status,'direct')}</div><div class="detail-card"><label>Documentos</label>${docsViewHTML(s.docs)||'<div class="muted">Nenhum documento.</div>'}</div><div class="detail-card"><label>Assinatura</label>${signatureViewHTML(s.signature)}</div><div class="actions premium-actions"><button class="primary" onclick="navigate('${s.id}')">Navegar</button><button class="secondary" onclick="nextStop('${s.id}')">Próxima</button><button class="secondary" onclick="openSignaturePadForStop('${s.id}')">Assinar</button><button class="secondary" onclick="quickAttachDoc('${s.id}')">Documento</button><button class="secondary" onclick="printStop('${s.id}')">Imprimir</button><button class="secondary" onclick="editStop('${s.id}')">Editar</button></div>`)}
function editStop(id){const s=route().stops.find(x=>x.id===id);closeModal(false);stopModal(s,false)}
function navigate(id){const s=route().stops.find(x=>x.id===id);const dest=Number.isFinite(s.lat)&&Number.isFinite(s.lng)?`${s.lat},${s.lng}`:s.address;window.location.href='https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(dest)+'&travelmode=driving'}
function nextStop(id){const r=route(),i=r.stops.findIndex(s=>s.id===id),n=r.stops.slice(i+1).find(s=>s.status==='pending')||r.stops.find(s=>s.status==='pending');if(n){closeModal(false);viewStop(n.id)}else toast('Não há outra parada pendente.')}
async function optimizeRoute(){const r=route(),located=r.stops.filter(s=>Number.isFinite(s.lat)&&Number.isFinite(s.lng)&&s.status==='pending');if(located.length<2){toast('São necessárias pelo menos 2 paradas pendentes com coordenadas.');return}const ordered=[located[0]],left=located.slice(1);while(left.length){const a=ordered[ordered.length-1];let best=0,bd=Infinity;left.forEach((b,i)=>{const d=haversine(a,b);if(d<bd){bd=d;best=i}});ordered.push(left.splice(best,1)[0])}const ids=new Set(ordered.map(s=>s.id)),rest=r.stops.filter(s=>!ids.has(s.id));r.stops=[...ordered,...rest];await saveVault();state.menu=false;renderRoute();toast('Diligências ordenadas por proximidade geográfica.')}
function haversine(a,b){const R=6371,p1=a.lat*Math.PI/180,p2=b.lat*Math.PI/180,dp=(b.lat-a.lat)*Math.PI/180,dl=(b.lng-a.lng)*Math.PI/180,x=Math.sin(dp/2)**2+Math.cos(p1)*Math.cos(p2)*Math.sin(dl/2)**2;return 2*R*Math.asin(Math.sqrt(x))}

async function chooseDocs(){const p=document.querySelector('#filePicker');p.value='';p.onchange=async()=>{for(const f of p.files){try{const id=uid();await secureDbPutEncrypted(f,id);modalStop.docs=modalStop.docs||[];modalStop.docs.push({id,name:f.name,type:f.type||'application/octet-stream',size:f.size});modalContext.addedDocIds.push(id)}catch(e){console.error(e);toast('Falha ao criptografar um documento.')}}const box=document.querySelector('#docs');if(box)box.innerHTML=docsEditHTML(modalStop.docs)};p.click()}
function docsEditHTML(docs=[]){return docs.map(d=>`<div class="doc"><span>📎 ${esc(d.name)}</span><button class="secondary" onclick="openDoc('${d.id}')">Abrir</button><button class="danger" onclick="removeDocTemp('${d.id}')">×</button></div>`).join('')}
function docsViewHTML(docs=[]){return docs.map(d=>`<div class="doc"><span>📎 ${esc(d.name)}</span><button class="secondary" onclick="openDoc('${d.id}')">Abrir</button></div>`).join('')}
async function openDoc(id){try{const rec=await secureDbGet(id);if(!rec)return toast('Documento não encontrado.');const plain=await decryptBytes(rec);const meta=(modalStop?.docs||[]).find(d=>d.id===id)||findDocMeta(id);const blob=new Blob([plain],{type:meta?.type||'application/octet-stream'});const url=URL.createObjectURL(blob);window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(e){console.error(e);toast('Não foi possível abrir o documento.') }}
function findDocMeta(id){for(const r of state.data.routes)for(const s of r.stops||[]){const d=(s.docs||[]).find(x=>x.id===id);if(d)return d;if(s.signature?.id===id)return s.signature}return null}
async function removeDocTemp(id){modalStop.docs=(modalStop.docs||[]).filter(d=>d.id!==id);const pos=modalContext.addedDocIds.indexOf(id);if(pos>=0){modalContext.addedDocIds.splice(pos,1);await secureDbDelete(id)}else modalContext.removedDocIds.push(id);const box=document.querySelector('#docs');if(box)box.innerHTML=docsEditHTML(modalStop.docs)}

function signatureEditHTML(sig){if(!sig)return '<div class="muted" style="margin-bottom:8px">Nenhuma assinatura coletada.</div>';return `<div class="doc"><span>✍️ ${esc(sig.name||'assinatura.jpg')}</span><button class="secondary" onclick="openDoc('${sig.id}')">Abrir</button><button class="danger" onclick="removeSignatureTemp()">×</button></div>`}
function signatureViewHTML(sig){if(!sig)return '<div class="muted">Nenhuma assinatura.</div>';return `<div class="doc"><span>✍️ ${esc(sig.name||'assinatura.jpg')}</span><button class="secondary" onclick="openDoc('${sig.id}')">Abrir JPEG</button></div>`}
async function removeSignatureTemp(){if(!modalStop?.signature)return;const id=modalStop.signature.id;modalStop.signature=null;const pos=modalContext?.addedDocIds?.indexOf(id)??-1;if(pos>=0){modalContext.addedDocIds.splice(pos,1);await secureDbDelete(id)}else if(modalContext?.removedDocIds&&!modalContext.removedDocIds.includes(id))modalContext.removedDocIds.push(id);const box=document.querySelector('#signatureBox');if(box)box.innerHTML=signatureEditHTML(null)}
async function importSignatureImage(){if(!modalStop||!modalContext)return;const i=document.createElement('input');i.type='file';i.accept='image/jpeg,image/png,image/webp';i.onchange=async()=>{const f=i.files?.[0];if(!f)return;try{const oldId=modalStop.signature?.id||null,id=uid();await secureDbPutEncrypted(f,id);modalStop.signature={id,name:f.name||`assinatura-${new Date().toISOString().slice(0,10)}.jpg`,type:f.type||'image/jpeg',size:f.size,createdAt:Date.now()};modalContext.addedDocIds=modalContext.addedDocIds||[];modalContext.removedDocIds=modalContext.removedDocIds||[];modalContext.addedDocIds.push(id);if(oldId){const pos=modalContext.addedDocIds.indexOf(oldId);if(pos>=0){modalContext.addedDocIds.splice(pos,1);await secureDbDelete(oldId)}else modalContext.removedDocIds.push(oldId)}document.querySelector('#signatureBox').innerHTML=signatureEditHTML(modalStop.signature);toast('Assinatura importada e criptografada.')}catch(e){console.error(e);toast('Não foi possível importar a assinatura.')}};i.click()}
async function quickAttachDoc(id){const s=route()?.stops.find(x=>x.id===id);if(!s)return;const i=document.createElement('input');i.type='file';i.accept='application/pdf,image/*';i.multiple=true;i.onchange=async()=>{try{for(const f of i.files||[]){const docId=uid();await secureDbPutEncrypted(f,docId);s.docs=s.docs||[];s.docs.push({id:docId,name:f.name,type:f.type||'application/octet-stream',size:f.size})}await saveVault();closeModal(false);viewStop(id);toast('Documento anexado.')}catch(e){console.error(e);toast('Falha ao anexar documento.')}};i.click()}
function openSignaturePadForStop(id){const s=route()?.stops.find(x=>x.id===id);if(!s)return;closeModal(false);stopModal(s,false);setTimeout(openSignaturePad,50)}
function openSignaturePad(){if(!modalStop||!modalContext)return;const old=document.querySelector('#signatureOverlay');if(old)old.remove();const o=document.createElement('div');o.id='signatureOverlay';o.className='signature-overlay';o.innerHTML=`<div class="signature-toolbar"><div><strong>Assinatura</strong><div class="signature-hint">Assine com o dedo ou caneta. Para melhor área, vire o celular na horizontal.</div></div><div class="signature-tools"><button class="secondary" onclick="clearSignaturePad()">Limpar</button><button class="secondary" onclick="closeSignaturePad()">Cancelar</button><button class="primary" onclick="saveSignaturePad()">Salvar JPEG</button></div></div><div class="signature-stage"><canvas id="signatureCanvas"></canvas></div>`;document.body.appendChild(o);document.body.classList.add('signature-open');try{document.documentElement.requestFullscreen?.().catch(()=>{});screen.orientation?.lock?.('landscape').catch(()=>{})}catch{};requestAnimationFrame(initSignatureCanvas)}
function initSignatureCanvas(){const c=document.querySelector('#signatureCanvas');if(!c)return;const stage=c.parentElement,ratio=Math.max(1,window.devicePixelRatio||1),rect=stage.getBoundingClientRect();c.width=Math.floor(rect.width*ratio);c.height=Math.floor(rect.height*ratio);c.style.width=rect.width+'px';c.style.height=rect.height+'px';const x=c.getContext('2d');x.setTransform(ratio,0,0,ratio,0,0);x.fillStyle='#fff';x.fillRect(0,0,rect.width,rect.height);x.strokeStyle='#111827';x.lineWidth=2.4;x.lineCap='round';x.lineJoin='round';let drawing=false,last=null;const point=e=>{const r=c.getBoundingClientRect(),p=e.touches?.[0]||e;return{x:p.clientX-r.left,y:p.clientY-r.top}};const down=e=>{e.preventDefault();drawing=true;last=point(e);x.beginPath();x.moveTo(last.x,last.y)};const move=e=>{if(!drawing)return;e.preventDefault();const p=point(e);x.lineTo(p.x,p.y);x.stroke();last=p};const up=e=>{if(!drawing)return;e?.preventDefault?.();drawing=false;last=null};c.addEventListener('pointerdown',down);c.addEventListener('pointermove',move);window.addEventListener('pointerup',up,{once:false});c.addEventListener('touchstart',down,{passive:false});c.addEventListener('touchmove',move,{passive:false});c.addEventListener('touchend',up,{passive:false})}
function clearSignaturePad(){const c=document.querySelector('#signatureCanvas');if(!c)return;const x=c.getContext('2d');x.save();x.setTransform(1,0,0,1,0,0);x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.restore()}
async function saveSignaturePad(){const c=document.querySelector('#signatureCanvas');if(!c)return;const blob=await new Promise(ok=>c.toBlob(ok,'image/jpeg',0.92));if(!blob)return toast('Não foi possível gerar a assinatura.');try{const oldId=modalStop.signature?.id||null,id=uid();await secureDbPutEncrypted(blob,id);modalStop.signature={id,name:`assinatura-${new Date().toISOString().slice(0,10)}.jpg`,type:'image/jpeg',size:blob.size,createdAt:Date.now()};modalContext.addedDocIds=modalContext.addedDocIds||[];modalContext.removedDocIds=modalContext.removedDocIds||[];modalContext.addedDocIds.push(id);if(oldId){const pos=modalContext.addedDocIds.indexOf(oldId);if(pos>=0){modalContext.addedDocIds.splice(pos,1);await secureDbDelete(oldId)}else if(!modalContext.removedDocIds.includes(oldId))modalContext.removedDocIds.push(oldId)}closeSignaturePad();const box=document.querySelector('#signatureBox');if(box)box.innerHTML=signatureEditHTML(modalStop.signature);toast('Assinatura salva em JPEG e criptografada.')}catch(e){console.error(e);toast('Falha ao salvar a assinatura.')}}
function closeSignaturePad(){document.querySelector('#signatureOverlay')?.remove();document.body.classList.remove('signature-open');try{screen.orientation?.unlock?.();if(document.fullscreenElement)document.exitFullscreen?.().catch(()=>{})}catch{}}

function secureDb(){return new Promise((ok,no)=>{const q=indexedDB.open('rotas-secure-docs',1);q.onupgradeneeded=()=>{if(!q.result.objectStoreNames.contains('docs'))q.result.createObjectStore('docs')};q.onsuccess=()=>ok(q.result);q.onerror=()=>no(q.error)})}
async function secureDbPutRecord(id,rec){const d=await secureDb();return new Promise((ok,no)=>{const tx=d.transaction('docs','readwrite');tx.objectStore('docs').put(rec,id);tx.oncomplete=()=>ok();tx.onerror=()=>no(tx.error)})}
async function secureDbPutEncrypted(blob,id=uid(),key=state.key){const buf=await blob.arrayBuffer();const rec=await encryptBytes(buf,key);await secureDbPutRecord(id,rec);return id}
async function secureDbGet(id){const d=await secureDb();return new Promise((ok,no)=>{const q=d.transaction('docs').objectStore('docs').get(id);q.onsuccess=()=>ok(q.result);q.onerror=()=>no(q.error)})}
async function secureDbDelete(id){const d=await secureDb();return new Promise(ok=>{const tx=d.transaction('docs','readwrite');tx.objectStore('docs').delete(id);tx.oncomplete=ok;tx.onerror=ok})}
async function clearSecureDocs(){const d=await secureDb();return new Promise(ok=>{const tx=d.transaction('docs','readwrite');tx.objectStore('docs').clear();tx.oncomplete=ok;tx.onerror=ok})}
function legacyDb(){return new Promise((ok,no)=>{const q=indexedDB.open('rotas-docs',1);q.onupgradeneeded=()=>{if(!q.result.objectStoreNames.contains('docs'))q.result.createObjectStore('docs')};q.onsuccess=()=>ok(q.result);q.onerror=()=>no(q.error)})}
async function legacyDbGet(id){try{const d=await legacyDb();return await new Promise((ok,no)=>{const q=d.transaction('docs').objectStore('docs').get(id);q.onsuccess=()=>ok(q.result);q.onerror=()=>no(q.error)})}catch{return null}}
async function legacyDbDelete(id){try{const d=await legacyDb();await new Promise(ok=>{const tx=d.transaction('docs','readwrite');tx.objectStore('docs').delete(id);tx.oncomplete=ok;tx.onerror=ok})}catch{}}
async function migrateLegacyDocs(data,key){for(const r of data.routes||[])for(const s of r.stops||[])for(const d of s.docs||[]){const blob=await legacyDbGet(d.id);if(blob){await secureDbPutEncrypted(blob,d.id,key);await legacyDbDelete(d.id)}}}

async function exportBackup(){try{const cfg=getConfig(),vault=JSON.parse(localStorage.getItem(VAULT_KEY));const ids=[...new Set(state.data.routes.flatMap(r=>r.stops||[]).flatMap(s=>[...(s.docs||[]).map(d=>d.id),...(s.signature?.id?[s.signature.id]:[])]))];const docs={};for(const id of ids){const rec=await secureDbGet(id);if(rec)docs[id]={iv:b64(rec.iv),data:b64(rec.data)}}const bundle={format:'rotas-secure-backup',version:2,exportedAt:new Date().toISOString(),kdf:{salt:cfg.salt,iterations:cfg.iterations},vault,docs};const blob=new Blob([JSON.stringify(bundle)],{type:'application/octet-stream'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='rotas-seguro-'+new Date().toISOString().slice(0,10)+'.rotasbackup';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Backup criptografado exportado.')}catch(e){console.error(e);toast('Falha ao exportar o backup.') }}
function importBackup(){const i=document.createElement('input');i.type='file';i.accept='.rotasbackup,application/json,application/octet-stream';i.onchange=async()=>{try{const bundle=JSON.parse(await i.files[0].text());if(bundle.format!=='rotas-secure-backup'||bundle.version!==2||!bundle.kdf||!bundle.vault)throw 0;pendingBackup=bundle;showModal(`<h2>Importar backup criptografado</h2><p>Digite o PIN/senha usado quando esse backup foi criado.</p><div class="warning">A importação substituirá as rotas e documentos atuais deste dispositivo.</div><div class="field"><label>PIN/senha do backup</label><input id="backupPass" type="password" autocomplete="current-password"></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="finishImportBackup()">Validar e importar</button></div>`)}catch{toast('Arquivo de backup inválido.')}};i.click()}
async function finishImportBackup(){const pass=document.querySelector('#backupPass').value;if(!pass)return;const b=pendingBackup;try{const key=await deriveKey(pass,b.kdf.salt,b.kdf.iterations);const data=await decryptJSON(b.vault,key);if(!Array.isArray(data.routes))throw 0;if(!confirm('Substituir todas as rotas e documentos atuais por este backup?'))return;await clearSecureDocs();for(const [id,rec] of Object.entries(b.docs||{}))await secureDbPutRecord(id,{iv:unb64(rec.iv),data:unb64(rec.data)});localStorage.setItem(CONFIG_KEY,JSON.stringify({version:2,salt:b.kdf.salt,iterations:b.kdf.iterations,createdAt:Date.now()}));localStorage.setItem(VAULT_KEY,JSON.stringify(b.vault));state.key=key;state.data=data;state.routeId=null;state.locked=false;pendingBackup=null;closeModal(false);render();toast('Backup importado. A senha ativa agora é a senha do backup.')}catch(e){console.error(e);toast('Senha incorreta ou backup corrompido.')}}

function securitySettings(){state.menu=false;const p=getPrefs();showModal(`<h2>Segurança e privacidade</h2><div class="security-note"><strong>Armazenamento:</strong> rotas e textos são criptografados com AES-GCM; a chave é derivada do seu PIN/senha por PBKDF2. PDFs e imagens também são criptografados antes de entrar no IndexedDB.</div><div class="field"><label>Bloqueio automático</label><select id="autoLock"><option value="5" ${p.autoLockMinutes===5?'selected':''}>5 minutos</option><option value="15" ${p.autoLockMinutes===15?'selected':''}>15 minutos</option><option value="30" ${p.autoLockMinutes===30?'selected':''}>30 minutos</option><option value="60" ${p.autoLockMinutes===60?'selected':''}>60 minutos</option></select></div><div class="field"><label>Mapa com ruas</label><div class="privacy-row"><input id="onlineMapConsent" type="checkbox" ${p.onlineMapConsent?'checked':''}><span>Carregar ruas do OpenStreetMap quando houver internet. Sem isso, o mapa espacial offline continua mostrando a posição relativa dos mandados.</span></div></div><div class="field"><label>Tamanho dos marcadores</label><select id="markerSize"><option value="small" ${p.markerSize==='small'?'selected':''}>Pequeno</option><option value="medium" ${p.markerSize==='medium'?'selected':''}>Médio</option><option value="large" ${p.markerSize==='large'?'selected':''}>Grande</option></select></div><div class="field"><label>Busca online de endereços</label><div class="privacy-row"><input id="addressConsent" type="checkbox" ${p.addressSearchConsent?'checked':''}><span>Permitir envio do texto do endereço ao Nominatim/OpenStreetMap quando eu tocar em “Buscar online”.</span></div></div><div class="warning">Ao tocar em <strong>Navegar</strong>, o destino é enviado ao Google Maps. Quando houver coordenadas, o app envia as coordenadas; sem coordenadas, envia o endereço.</div><div class="modal-actions"><button class="secondary" onclick="lockNow()">Bloquear agora</button><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveSecuritySettings()">Salvar</button></div>`)}
function saveSecuritySettings(){const mins=parseInt(document.querySelector('#autoLock').value,10),consent=document.querySelector('#addressConsent').checked,mapConsent=document.querySelector('#onlineMapConsent').checked,markerSize=document.querySelector('#markerSize')?.value||'medium';setPrefs({autoLockMinutes:mins,addressSearchConsent:consent,onlineMapConsent:mapConsent,markerSize});closeModal();touch();toast('Preferências salvas.');if(state.routeId)renderRoute()}


function visualSettings(){state.menu=false;const p=getPrefs();showModal(`<h2>Aparência do mapa</h2><div class="field"><label>Tamanho dos marcadores</label><div class="segmented"><button class="${p.markerSize==='small'?'active':''}" onclick="setMarkerSize('small')">Pequeno</button><button class="${p.markerSize==='medium'?'active':''}" onclick="setMarkerSize('medium')">Médio</button><button class="${p.markerSize==='large'?'active':''}" onclick="setMarkerSize('large')">Grande</button></div></div><div class="security-note">A alteração afeta os marcadores do mapa online e do mapa espacial offline.</div><div class="modal-actions"><button class="primary" onclick="closeModal();renderRoute()">Concluir</button></div>`)}
function setMarkerSize(v){setPrefs({markerSize:v});document.querySelectorAll('.segmented button').forEach(b=>b.classList.toggle('active',b.textContent.toLowerCase().startsWith(v==='small'?'peq':v==='medium'?'méd':'gra')))}
function parseCSV(text){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'){if(q&&n==='"'){cell+='"';i++}else q=!q}else if(c===','&&!q){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&n==='\n')i++;row.push(cell);cell='';if(row.some(v=>v.trim()!==''))rows.push(row);row=[]}else cell+=c}row.push(cell);if(row.some(v=>v.trim()!==''))rows.push(row);if(rows.length<2)return[];const h=rows[0].map(x=>x.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,''));return rows.slice(1).map(r=>Object.fromEntries(h.map((k,i)=>[k,(r[i]||'').trim()]))) }
function normalizeImportedStop(x){if(Array.isArray(x))x={nome:x[0]||'',endereco:x[1]||'',observacoes:x[2]||''};const num=x.numero||x.numeromandado||x.mandado||x.number||'';const name=x.nome||x.pessoa||x.name||'';const address=x.endereco||x.address||'';const notes=x.observacoes||x.dados||x.notes||'';const lat=parseFloat(String(x.latitude??x.lat??'').replace(',','.')),lng=parseFloat(String(x.longitude??x.lng??x.lon??'').replace(',','.'));let color=x.cor||x.color||COLORS[3];if(!/^#[0-9a-f]{6}$/i.test(color))color=COLORS[3];let status=String(x.status||'pending').toLowerCase();if(['entregue','delivered','feito'].includes(status))status='delivered';else if(['nao entregue','não entregue','failed','negativo'].includes(status))status='failed';else status='pending';return{id:uid(),name:String(name).trim(),number:String(num).trim(),address:String(address).trim(),notes:String(notes).trim(),color,status,lat:Number.isFinite(lat)?lat:null,lng:Number.isFinite(lng)?lng:null,docs:[],signature:null}}
function parsePastedStops(text){const t=(text||'').trim();if(!t)return[];if(t.startsWith('[')||t.startsWith('{')){const parsed=JSON.parse(t);const raw=Array.isArray(parsed)?parsed:(parsed.stops||parsed.diligencias||[]);return raw.map(normalizeImportedStop).filter(s=>s.name||s.address||s.number)}const lines=t.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);return lines.map(line=>{let parts;if(line.includes('\t'))parts=line.split('\t');else if(line.includes('|'))parts=line.split('|');else if(line.includes(';'))parts=line.split(';');else return null;parts=parts.map(x=>x.trim());return normalizeImportedStop({nome:parts[0]||'',endereco:parts[1]||'',observacoes:parts.slice(2).join(' | ')})}).filter(s=>s&&(s.name||s.address||s.number))}
async function addImportedStops(stops){if(!stops.length)throw new Error('empty');route().stops.push(...stops);await saveVault();closeModal(false);renderRoute();const missing=stops.filter(s=>s.address&&(!Number.isFinite(s.lat)||!Number.isFinite(s.lng))).length;if(missing&&navigator.onLine){setTimeout(()=>showModal(`<h2>Importação concluída</h2><p><strong>${stops.length}</strong> diligência${stops.length===1?'':'s'} importada${stops.length===1?'':'s'}.</p><p>${missing} endereço${missing===1?' ainda não tem':'s ainda não têm'} coordenadas. Para aparecer como marcador no mapa, o aplicativo precisa localizar ${missing===1?'esse endereço':'esses endereços'}.</p><div class="security-note">Na localização online, somente o texto de cada endereço é enviado ao serviço Nominatim/OpenStreetMap. Nome da pessoa, dados do mandado, documentos, assinatura e status não são enviados.</div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Depois</button><button class="primary" onclick="locateMissingAddresses(true)">Localizar agora</button></div>`),120)}else toast(`${stops.length} diligência${stops.length===1?'':'s'} importada${stops.length===1?'':'s'}.`)}

let bulkGeoCancelled=false;
function missingAddressStops(){return (route()?.stops||[]).filter(s=>s.address&&(!Number.isFinite(s.lat)||!Number.isFinite(s.lng)))}
function cancelBulkGeocode(){bulkGeoCancelled=true;const b=document.querySelector('#bulkGeoCancel');if(b){b.disabled=true;b.textContent='Cancelando…'}}
async function locateMissingAddresses(fromImport=false){state.menu=false;const missing=missingAddressStops();if(!missing.length){if(fromImport)closeModal();toast('Todos os endereços já têm coordenadas.');return}if(!navigator.onLine){if(fromImport)closeModal();toast('Conecte à internet para localizar os endereços.');return}if(!getPrefs().addressSearchConsent){showModal(`<h2>Localizar endereços</h2><p>Existem <strong>${missing.length}</strong> diligência${missing.length===1?'':'s'} sem coordenadas.</p><p>Para transformá-las em marcadores no mapa, o aplicativo consultará o Nominatim/OpenStreetMap, uma por vez.</p><div class="warning">Somente o texto do endereço é enviado ao serviço externo. Nome da pessoa, número e dados do mandado, documentos, assinatura e status permanecem locais.</div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="allowBulkGeocode()">Permitir e localizar</button></div>`);return}await runBulkGeocode()}
async function allowBulkGeocode(){setPrefs({addressSearchConsent:true});await runBulkGeocode()}
async function geocodeOneAddress(address){const url='https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=br&accept-language=pt-BR&q='+encodeURIComponent(address);for(let attempt=0;attempt<2;attempt++){const res=await fetch(url,{cache:'no-store'});if(res.status===429||res.status===503){await new Promise(r=>setTimeout(r,2500));continue}if(!res.ok)throw new Error('HTTP '+res.status);const arr=await res.json();return arr?.[0]||null}return null}
async function runBulkGeocode(){const missing=missingAddressStops();if(!missing.length){closeModal();toast('Todos os endereços já têm coordenadas.');return}bulkGeoCancelled=false;showModal(`<h2>Localizando endereços</h2><p id="bulkGeoText">Preparando ${missing.length} consulta${missing.length===1?'':'s'}…</p><div class="detail-card"><label>Progresso</label><div id="bulkGeoProgress" style="font-size:24px;font-weight:900">0 / ${missing.length}</div><div id="bulkGeoCurrent" class="muted" style="margin-top:6px"></div></div><div class="tiny">As consultas são feitas em sequência, com intervalo entre elas, para não sobrecarregar o serviço de geocodificação.</div><div class="modal-actions"><button id="bulkGeoCancel" class="secondary" onclick="cancelBulkGeocode()">Cancelar</button></div>`);let found=0,failed=0,done=0;for(const s of missing){if(bulkGeoCancelled)break;const current=document.querySelector('#bulkGeoCurrent');if(current)current.textContent=s.address;try{const x=await geocodeOneAddress(s.address);if(x){const lat=parseFloat(x.lat),lng=parseFloat(x.lon);if(Number.isFinite(lat)&&Number.isFinite(lng)){s.lat=lat;s.lng=lng;found++}else failed++}else failed++}catch(e){console.warn('Falha ao localizar',s.address,e);failed++}done++;const prog=document.querySelector('#bulkGeoProgress');if(prog)prog.textContent=`${done} / ${missing.length}`;if(done%5===0)await saveVault();if(done<missing.length&&!bulkGeoCancelled)await new Promise(r=>setTimeout(r,1100))}await saveVault();const cancelled=bulkGeoCancelled;closeModal(false);renderRoute();toast(cancelled?`Localização interrompida: ${found} encontrado${found===1?'':'s'}.`:`Localização concluída: ${found} encontrado${found===1?'':'s'}${failed?`, ${failed} não localizado${failed===1?'':'s'}`:''}.`)}

function importStops(){state.menu=false;showModal(`<h2>Importar diligências</h2><p class="muted">Para o uso rápido, basta informar <strong>nome</strong> e <strong>endereço</strong>. Os demais dados podem ser acrescentados depois.</p><div class="field"><label>Colar lista</label><textarea id="pasteStops" rows="9" placeholder="João da Silva | Rua Paraná, 3505, Ariquemes - RO\nMaria Souza | Av. Tancredo Neves, 1200, Ariquemes - RO"></textarea><div class="tiny">Aceita uma linha por pessoa usando |, ponto e vírgula ou texto copiado de duas colunas de uma planilha. Também aceita JSON.</div></div><div class="import-example"><strong>JSON simples aceito:</strong><pre>[{"nome":"João da Silva","endereco":"Rua Paraná, 3505"}]</pre></div><div class="modal-actions import-actions"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="secondary" onclick="importStopsFile()">Escolher CSV/JSON</button><button class="primary" onclick="importPastedStops()">Importar texto</button></div>`)}
async function importPastedStops(){try{const stops=parsePastedStops(document.querySelector('#pasteStops')?.value||'');await addImportedStops(stops)}catch(e){console.error(e);toast('Não consegui interpretar a lista. Use Nome | Endereço ou JSON válido.')}}
function importStopsFile(){const i=document.createElement('input');i.type='file';i.accept='.csv,.json,text/csv,application/json';i.onchange=async()=>{const f=i.files?.[0];if(!f)return;try{let raw=[];if(f.name.toLowerCase().endsWith('.json')){const parsed=JSON.parse(await f.text());raw=Array.isArray(parsed)?parsed:(parsed.stops||parsed.diligencias||[])}else raw=parseCSV(await f.text());const stops=raw.map(normalizeImportedStop).filter(s=>s.name||s.address||s.number);await addImportedStops(stops)}catch(e){console.error(e);toast('Arquivo inválido. Use CSV ou JSON.')}};i.click()}
function downloadImportTemplate(){const csv='nome,endereco\nJoão da Silva,Rua Paraná 3505 - Ariquemes RO\nMaria Souza,Av. Tancredo Neves 1200 - Ariquemes RO\n';const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='modelo-importacao-diligencias.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function reportHTML(r,onlyId=null){const stops=onlyId?r.stops.filter(s=>s.id===onlyId):r.stops;const statusLabel=s=>(s.status||'pending')==='delivered'?'Entregue':(s.status||'pending')==='failed'?'Não entregue':'Pendente';return `<!doctype html><html><head><meta charset="utf-8"><title>${esc(r.name)}</title><style>body{font-family:Arial,sans-serif;color:#111;margin:32px}h1{margin:0 0 4px}.muted{color:#666;font-size:12px}.summary{display:flex;gap:14px;margin:20px 0;padding:12px;border:1px solid #ddd;border-radius:10px}.card{break-inside:avoid;border-top:1px solid #ddd;padding:14px 0}.num{font-weight:700}.status{font-weight:700}.notes{white-space:pre-wrap;margin-top:8px}.meta{font-size:12px;color:#555;margin-top:6px}@media print{button{display:none}body{margin:16mm}}</style></head><body><h1>${esc(r.name)}</h1><div class="muted">Relatório gerado em ${new Date().toLocaleString('pt-BR')}</div><div class="summary"><span>Total: <b>${stops.length}</b></span><span>Pendentes: <b>${stops.filter(s=>(s.status||'pending')==='pending').length}</b></span><span>Não entregues: <b>${stops.filter(s=>s.status==='failed').length}</b></span><span>Entregues: <b>${stops.filter(s=>s.status==='delivered').length}</b></span></div>${stops.map((s,i)=>`<section class="card"><div><span class="num">${onlyId?'':(i+1)+'. '}${esc(s.name||'Sem nome')}</span>${s.number?` — Mandado ${esc(s.number)}`:''}</div><div>${esc(s.address||'Sem endereço')}</div><div class="status">${statusLabel(s)}</div>${s.notes?`<div class="notes">${esc(s.notes)}</div>`:''}<div class="meta">Documentos: ${(s.docs||[]).length} · Assinatura: ${s.signature?'sim':'não'}${Number.isFinite(s.lat)&&Number.isFinite(s.lng)?` · ${s.lat}, ${s.lng}`:''}</div></section>`).join('')}<script>window.onload=()=>setTimeout(()=>window.print(),250)<\/script></body></html>`}
function openPrintWindow(html){const w=window.open('','_blank');if(!w){toast('Permita pop-ups para imprimir o relatório.');return}w.document.open();w.document.write(html);w.document.close()}
function printRouteReport(){state.menu=false;const r=route();if(r)openPrintWindow(reportHTML(r))}
function printStop(id){const r=route();if(r)openPrintWindow(reportHTML(r,id))}
function showModal(html){closeModal(false);const b=document.createElement('div');b.className='modal-back';b.id='modalBack';b.innerHTML=`<div class="modal">${html}</div>`;document.body.appendChild(b);touch()}
function closeModal(resetContext=true){document.querySelector('#modalBack')?.remove();if(resetContext){modalStop=null;modalContext=null}}
function showNestedConfirm(html){const b=document.createElement('div');b.className='modal-back';b.id='nestedModal';b.style.zIndex='3000';b.innerHTML=`<div class="modal">${html}</div>`;document.body.appendChild(b)}
function closeNestedConfirm(){document.querySelector('#nestedModal')?.remove()}

async function boot(){if(!window.crypto?.subtle){document.querySelector('#app').innerHTML='<div class="auth-shell"><div class="auth-card"><h1>Navegador incompatível</h1><p>Este aplicativo exige Web Crypto para proteger os dados. Use uma versão atual do Safari, Chrome, Edge ou Firefox.</p></div></div>';return}if(!getConfig())renderSetup();else renderLock();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw-v3.6.js').catch(()=>{});['pointerdown','keydown','touchstart'].forEach(ev=>document.addEventListener(ev,touch,{passive:true}));setInterval(()=>{if(!state.locked){const mins=getPrefs().autoLockMinutes||15;if(Date.now()-state.lastActivity>mins*60000)lockNow()}},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!state.locked){const mins=getPrefs().autoLockMinutes||15;if(Date.now()-state.lastActivity>mins*60000)lockNow()}})}
boot();
